import{_ as o,o as r,c as d,a2 as a}from"./chunks/framework.DGvnA5EY.js";const s="/workbuddy-guide/assets/02-official-new-task.CJulLJlb.png",e="/workbuddy-guide/assets/01-three-elements-funnel.CNE22dA2.png",n="/workbuddy-guide/assets/03-official-template-preview.tNJnCxJ-.png",l="/workbuddy-guide/assets/04-official-workbench-overview.DQxfaWoG.png",i="/workbuddy-guide/assets/09-official-artifact-list.1p-6Qvw_.png",g="/workbuddy-guide/assets/05-official-artifact-share.CHN1y69w.png",p="/workbuddy-guide/assets/06-official-upload-cloud.PA3T0X1N.png",u="/workbuddy-guide/assets/08-official-multi-tab.Csb5NPOL.png",h="/workbuddy-guide/assets/07-official-changes-view.CgDwNO45.png",x=JSON.parse('{"title":"第 4 章 快速完成第一个 WorkBuddy 任务","description":"> 内容来源：WorkBuddy 官方指南 · 创建任务 / 任务管理 / 结果查看（非官方整理，© 本指南作者，保留所有权利） 前面两章你已经装好软件、认清了导航栏。这一章真正动手——跑通你的第一个任务。","frontmatter":{"title":"第 4 章 快速完成第一个 WorkBuddy 任务"},"headers":[],"relativePath":"bluebook/第一篇 使用手册：先把 WorkBuddy 用起来/第 4 章 快速完成第一个 WorkBuddy 任务/index.md","filePath":"bluebook/第一篇 使用手册：先把 WorkBuddy 用起来/第 4 章 快速完成第一个 WorkBuddy 任务/index.md","lastUpdated":1791629861000}'),c={name:"bluebook/第一篇 使用手册：先把 WorkBuddy 用起来/第 4 章 快速完成第一个 WorkBuddy 任务/index.md"};function b(q,t,m,k,y,f){return r(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="第-4-章-快速完成第一个-workbuddy-任务" tabindex="-1">第 4 章 快速完成第一个 WorkBuddy 任务 <a class="header-anchor" href="#第-4-章-快速完成第一个-workbuddy-任务" aria-label="Permalink to &quot;第 4 章 快速完成第一个 WorkBuddy 任务&quot;">​</a></h1><blockquote><p>内容来源：WorkBuddy 官方指南 · 创建任务 / 任务管理 / 结果查看（非官方整理，© 本指南作者，保留所有权利）</p></blockquote><p>前面两章你已经装好软件、认清了导航栏。这一章真正动手——<strong>跑通你的第一个任务</strong>。</p><p>这一章最重要的不是&quot;让它做出多厉害的东西&quot;，而是<strong>跑通一次完整闭环</strong>： 提需求 → 看它干活 → 收到结果 → 验收。走通这一遍，后面所有章节都是这个 闭环的变体。</p><h2 id="一、创建任务-三种方式任选" tabindex="-1">一、创建任务：三种方式任选 <a class="header-anchor" href="#一、创建任务-三种方式任选" aria-label="Permalink to &quot;一、创建任务：三种方式任选&quot;">​</a></h2><p>在左侧导航栏点**「新建任务」**，会进入创建任务页。你可以从三个入口开始：</p><table tabindex="0"><thead><tr><th>方式</th><th>怎么做</th><th>适合谁</th></tr></thead><tbody><tr><td>直接说人话</td><td>在输入框写一句话需求</td><td>第一次用，先试试水</td></tr><tr><td>用提示词模板</td><td>悬停在模板上看预览，合适就点</td><td>不知道怎么组织需求</td></tr><tr><td>从任务列表继续</td><td>打开旧任务补一句</td><td>上次没做完，想接着来</td></tr></tbody></table><p><strong>重点提醒</strong>：官方文档明确说了 WorkBuddy 的核心优势是理解自然语言， <strong>你不需要预先把任务拆成步骤</strong>。把&quot;要什么结果&quot;讲清楚就够了，拆步骤是它的事。</p><p><img src="'+s+'" alt="创建任务后的对话区：输入框提示「今天帮你做些什么」，下方列出本次产出文件" loading="lazy"></p><p><em>此图片来自官方。</em></p><h2 id="二、把需求说清楚的公式-要什么-给什么-交付成什么样" tabindex="-1">二、把需求说清楚的公式：要什么 + 给什么 + 交付成什么样 <a class="header-anchor" href="#二、把需求说清楚的公式-要什么-给什么-交付成什么样" aria-label="Permalink to &quot;二、把需求说清楚的公式：要什么 + 给什么 + 交付成什么样&quot;">​</a></h2><p>这是本节最该记住的一段。新手最容易犯的错是只说一句&quot;帮我整理一下&quot;， 然后抱怨它理解错了。</p><table tabindex="0"><thead><tr><th>要素</th><th>反面例子</th><th>正面例子</th></tr></thead><tbody><tr><td><strong>要什么</strong></td><td>整理一下文件</td><td>按类型把这批照片分类整理好</td></tr><tr><td><strong>给什么</strong></td><td>（没说）</td><td>桌面「测试文件夹」里的 10 张图 + 3 个 PDF</td></tr><tr><td><strong>交付成什么样</strong></td><td>（没说）</td><td>图片放「图片」子文件夹，PDF 放「文档」子文件夹</td></tr></tbody></table><p><img src="'+e+'" alt="三要素逐层补充，缺一项结果就会跑偏" loading="lazy"></p><p><em>配图为示意插画，用于帮助理解三要素的关系，与实际软件界面无关。</em></p><p>官方给的示范句式，可以直接套用：</p><ul><li>&quot;帮我把这份销售数据生成一个分析报告，包含图表&quot;</li><li>&quot;整理 Downloads 文件夹里的图片，按日期分类&quot;</li><li>&quot;根据这份会议纪要生成一个 PPT&quot;</li><li>&quot;分析这份简历，提取关键信息生成表格&quot;</li><li>&quot;调研一下 2024 年 AI 行业趋势，写一份报告&quot;</li></ul><p><strong>看出规律了吗？</strong> 每句都包含了目标动作 + 明确的输入来源 + 期望的输出形态。 照这个结构写，结果就可控了。</p><h2 id="三、四种补充上下文的方式-让需求更精准" tabindex="-1">三、四种补充上下文的方式（让需求更精准） <a class="header-anchor" href="#三、四种补充上下文的方式-让需求更精准" aria-label="Permalink to &quot;三、四种补充上下文的方式（让需求更精准）&quot;">​</a></h2><p>除了写清楚需求，你还可以给它更多&quot;背景资料&quot;：</p><table tabindex="0"><thead><tr><th>方式</th><th>操作</th><th>白话解释</th></tr></thead><tbody><tr><td><strong>引用上下文</strong></td><td>输入 <code>@</code> 引用文件、文档、规则</td><td>明确告诉它&quot;参考这个&quot;</td></tr><tr><td><strong>粘贴截图</strong></td><td><code>Ctrl/Cmd + V</code> 直接粘贴</td><td>你看到什么它就看到什么</td></tr><tr><td><strong>上传文件</strong></td><td>点上传按钮，或直接拖文件进输入框</td><td>把素材递给它</td></tr><tr><td><strong>补充说明</strong></td><td>在描述里写清目标、范围、约束</td><td>划定边界，别让它跑偏</td></tr></tbody></table><p><strong>优先补这四类信息</strong>：目标是什么、输入是什么、输出格式（Word/Excel/PPT）、 约束条件（风格、字数、截止时间）。</p><h3 id="提示词模板的妙用-灰字只是预览-不会被你误发" tabindex="-1">提示词模板的妙用：灰字只是预览，不会被你误发 <a class="header-anchor" href="#提示词模板的妙用-灰字只是预览-不会被你误发" aria-label="Permalink to &quot;提示词模板的妙用：灰字只是预览，不会被你误发&quot;">​</a></h3><p>创建任务页按场景（日常办公、代码开发、设计创意）提供了一组提示词模板。 <strong>把鼠标悬停在模板上，输入框会即时显示灰色预览文案</strong>，你可以先看清内容再决定要不要用。</p><p>这里有个新手常误会的地方，官方文档专门强调过：</p><blockquote><ul><li>灰字<strong>仅供预览</strong>，不会进入草稿、撤销记录，<strong>也不会被发送</strong>；</li><li>输入框已有文字时，预览接在已有内容末尾，黑色原文保持不变；</li><li>移开鼠标、失去焦点或切换场景后，预览自动清除；</li><li><strong>确认合适后点击模板</strong>，才会真正填入输入框。</li></ul></blockquote><p>所以你可以放心地一个个悬停过去比对，不满意的一概不会留在框里。</p><p><img src="'+n+'" alt="提示词模板的灰字预览：灰色部分是预览，不会被发送" loading="lazy"></p><p><em>此图片来自官方。</em></p><h2 id="四、选择工作空间-告诉它-在哪个目录干活" tabindex="-1">四、选择工作空间：告诉它&quot;在哪个目录干活&quot; <a class="header-anchor" href="#四、选择工作空间-告诉它-在哪个目录干活" aria-label="Permalink to &quot;四、选择工作空间：告诉它&quot;在哪个目录干活&quot;&quot;">​</a></h2><p>输入框左下角有**「选择工作空间」<strong>，点它选一个目录。选定后，WorkBuddy 会</strong>基于该目录读取和处理文件**。</p><p>不选也行 —— 它会在默认目录里生成结果。但如果你要做的事跟某个具体文件夹有关 （比如&quot;整理我的下载目录&quot;），<strong>选对工作空间能省掉很多纠偏沟通</strong>。</p><h2 id="五、任务创建成功后会发生什么" tabindex="-1">五、任务创建成功后会发生什么 <a class="header-anchor" href="#五、任务创建成功后会发生什么" aria-label="Permalink to &quot;五、任务创建成功后会发生什么&quot;">​</a></h2><p>点下发送，任务就建好了。你会看到：</p><ol><li><strong>新任务出现在左侧任务列表里</strong></li><li><strong>对话区持续展示它的执行过程</strong>——它会把每一步在干什么打出来给你看</li><li><strong>右侧结果区按任务类型展示产物、全部文件、变更和预览</strong></li><li><strong>可以继续补消息，也可以同时建别的任务并行推进</strong></li></ol><h2 id="六、看结果-右侧结果区的四类内容" tabindex="-1">六、看结果：右侧结果区的四类内容 <a class="header-anchor" href="#六、看结果-右侧结果区的四类内容" aria-label="Permalink to &quot;六、看结果：右侧结果区的四类内容&quot;">​</a></h2><p>结果区集中在一块区域，方便你来回切换对照：</p><table tabindex="0"><thead><tr><th>类型</th><th>看什么</th><th>什么时候重点看</th></tr></thead><tbody><tr><td><strong>概览 → 工作空间文件</strong></td><td>当前工作空间里的文件内容</td><td>想确认它有没有写错位置</td></tr><tr><td><strong>概览 → 浏览器</strong></td><td>网页或可直接打开的结果页面</td><td>它做的是网页/原型时</td></tr><tr><td><strong>概览 → 变更</strong></td><td>本次任务带来的文件修改</td><td><strong>代码、脚本、配置类任务必看</strong></td></tr><tr><td><strong>产物</strong></td><td>生成的文档、表格、PPT、报告</td><td>交付前最后确认</td></tr></tbody></table><p><img src="'+l+'" alt="完整工作界面：左侧导航栏、中间对话区、右侧浏览器预览" loading="lazy"></p><p><em>此图片来自官方。</em></p><p>任务跑完后，对话区下方会列出这次产出的所有文件，右侧可以直接预览内容：</p><p><img src="'+i+'" alt="对话区下方的产物列表，右侧为文件预览区" loading="lazy"></p><p><em>此图片来自官方。</em></p><h3 id="产物的分享与上传" tabindex="-1">产物的分享与上传 <a class="header-anchor" href="#产物的分享与上传" aria-label="Permalink to &quot;产物的分享与上传&quot;">​</a></h3><p>预览产物时点右上角的分享图标可以直接分享；也支持上传到 <strong>我的云端网盘、腾讯文档、ima 知识库、乐享知识库</strong> —— 在其他端的 WorkBuddy 应用内也能查看。</p><p><img src="'+g+'" alt="产物预览右上角的分享图标（红框标出）" loading="lazy"></p><p><em>此图片来自官方。</em></p><p><img src="'+p+'" alt="上传到云端的下拉菜单，四个目标位置" loading="lazy"></p><p><em>此图片来自官方。</em></p><h3 id="做了网页-内置浏览器直接看" tabindex="-1">做了网页？内置浏览器直接看 <a class="header-anchor" href="#做了网页-内置浏览器直接看" aria-label="Permalink to &quot;做了网页？内置浏览器直接看&quot;">​</a></h3><p>如果任务生成的是网页、页面原型或本地启动的 Web 应用，内置浏览器里 能直接看效果，还会提供页面地址、刷新入口。产物栏支持<strong>同时开多个浏览器页签</strong> （导航栏右侧的 <code>+</code> 号新建），每个页签保持独立的浏览状态，可以来回对比。</p><p><img src="'+u+'" alt="产物栏支持多个浏览器页签，各自独立浏览状态" loading="lazy"></p><p><em>此图片来自官方。</em></p><p><strong>一个实用建议</strong>：接受结果前先点一遍「变更」。如果任务涉及代码开发、脚本生成 或配置调整，这一步能帮你在结果落到文件之前就发现问题。</p><p><img src="'+h+'" alt="变更视图列出被修改的文件和改动行数" loading="lazy"></p><p><em>此图片来自官方。</em></p><h2 id="七、任务状态-知道它在干什么-也知道什么时候该介入" tabindex="-1">七、任务状态：知道它在干什么，也知道什么时候该介入 <a class="header-anchor" href="#七、任务状态-知道它在干什么-也知道什么时候该介入" aria-label="Permalink to &quot;七、任务状态：知道它在干什么，也知道什么时候该介入&quot;">​</a></h2><p>左侧任务列表的状态标记，是你判断&quot;要不要管它&quot;的依据：</p><table tabindex="0"><thead><tr><th>状态</th><th>含义</th><th>你该做什么</th></tr></thead><tbody><tr><td><strong>进行中</strong></td><td>正在执行</td><td>等</td></tr><tr><td><strong>已完成未读</strong></td><td>做完了，你还没看结果</td><td><strong>去看结果</strong></td></tr><tr><td><strong>待确认</strong></td><td>停下来等你确认或补充信息</td><td><strong>去回应它</strong></td></tr><tr><td>规划中</td><td>正在分析需求、整理思路</td><td>等</td></tr><tr><td>失败</td><td>执行中出问题</td><td>看报错，补信息重试</td></tr><tr><td>已归档</td><td>已归档，供查阅</td><td>不用管</td></tr></tbody></table><p>分组收起时，需要关注的状态会<strong>聚合显示在分组标题右侧</strong>，只显示优先级最高的那个， 优先级是：<strong>待确认 &gt; 已完成未读 &gt; 进行中</strong>。点它可以直接跳到第一个待处理的任务。</p><p><strong>&quot;待确认&quot;这个状态最值得注意</strong> —— 它意味着它在等你给指令，你不回，它就停在那。</p><h2 id="八、结果不满意-接着聊就行-不用重来" tabindex="-1">八、结果不满意？接着聊就行，不用重来 <a class="header-anchor" href="#八、结果不满意-接着聊就行-不用重来" aria-label="Permalink to &quot;八、结果不满意？接着聊就行，不用重来&quot;">​</a></h2><p>已完成、失败或暂时中断的任务，都可以<strong>重新进去继续补消息</strong>。 它会<strong>在已有上下文基础上继续推进</strong>，不用你从头再讲一遍。</p><p>适合继续处理的三种情况：</p><ul><li>第一次结果不够完整，想继续细化</li><li>执行失败了，补充信息后再试一次</li><li>想基于之前的结果扩展新需求</li></ul><h2 id="九、一个坑-删除任务无法恢复" tabindex="-1">九、一个坑：删除任务无法恢复 <a class="header-anchor" href="#九、一个坑-删除任务无法恢复" aria-label="Permalink to &quot;九、一个坑：删除任务无法恢复&quot;">​</a></h2><p>在任务行上悬停点「⋯」或直接右键，菜单里既有删除，也有置顶、重命名、保存到 工作空间、分享任务等操作。注意区分删除的后果：</p><table tabindex="0"><thead><tr><th>任务状态</th><th>删除后果</th></tr></thead><tbody><tr><td>普通任务</td><td>从<strong>所有设备</strong>移除，<strong>无法恢复</strong></td></tr><tr><td>正在运行的任务</td><td><strong>立即终止运行</strong>，无法恢复</td></tr></tbody></table><p>删除确认弹窗会直接出现在任务行旁边，键盘用 <code>Enter</code> 确认、<code>Esc</code> 取消。</p><p><strong>应对</strong>：不确定的任务先「归档」而不是删除——归档后还能在 「系统设置 - 数据管理」里找到。另外如果列表里有一堆要清理的， 可以用右键「批量操作」，但<strong>正在运行的任务无法勾选</strong>，得等它结束或先停止。</p><h2 id="十、本章任务清单-做完就算过关" tabindex="-1">十、本章任务清单（做完就算过关） <a class="header-anchor" href="#十、本章任务清单-做完就算过关" aria-label="Permalink to &quot;十、本章任务清单（做完就算过关）&quot;">​</a></h2><ul><li>[ ] 独立创建了一个任务，用的是&quot;要什么 + 给什么 + 交付成什么样&quot;的结构</li><li>[ ] 用 <code>@</code> 引用过文件，或上传过一个文件作为上下文</li><li>[ ] 故意悬停试了几个提示词模板，确认灰字预览不会污染输入框</li><li>[ ] 选过工作空间，知道它默认在哪个目录干活</li><li>[ ] 在结果区找到「产物」，确认看到了自己要的交付物</li><li>[ ] 点过一次「变更」，看过这次任务到底改了什么</li><li>[ ] 认得「已完成未读」和「待确认」两个状态的含义</li><li>[ ] 知道删除不可恢复，以及&quot;归档&quot;是更安全的选择</li></ul><hr><h2 id="小白说明书" tabindex="-1">小白说明书 <a class="header-anchor" href="#小白说明书" aria-label="Permalink to &quot;小白说明书&quot;">​</a></h2><blockquote><p>这一章术语密度比较高，这里统一解释。看完正文操作没问题的话，这段可以当复读材料。</p></blockquote><p><strong>工作空间（Workspace）</strong> 就是&quot;这次任务在哪个文件夹里干活&quot;。你选定一个目录，WorkBuddy 就在这个目录里 读文件、写结果。可以理解为给 AI 指一个&quot;工作台&quot;。不选也能用，它会用默认目录。</p><p><strong>上下文（Context）</strong> &quot;上下文&quot;在这里就是<strong>你递给它的背景资料</strong>。同一个需求，给不给上下文， 结果质量差很多。比如你说&quot;分析这份数据&quot;——不指文件它不知道分析哪份， 指了它就明确了。</p><p><strong><code>@</code> 引用</strong> 一个快捷记号。输入 <code>@</code> 会弹出可选项，选中的文件/文档就&quot;贴&quot;到了你的需求里， 相当于明确告诉它&quot;参考这个&quot;。不用去翻路径打字。</p><p><strong>提示词模板 / 灰字预览</strong> 模板是官方准备好的现成需求句式。<strong>悬停时看到的灰字只是给你预览的示意</strong>， 不会真的填进去、也不会发出去。你得<strong>点一下模板</strong>才真的填入。 这是官方特意设计的，防止手滑把不需要的内容发出去。</p><p><strong>产物</strong> 任务做完后交付给你的东西。文档、表格、PPT、报告、图片都算&quot;产物&quot;。 产品说明书里的正式说法，但理解成&quot;成果&quot;就对了。</p><p><strong>变更（Diff）</strong> 这次任务<strong>改动了哪些文件、改了什么内容</strong>的对照视图。改了文件的任务 （写代码、改配置、跑脚本）<strong>接受结果前一定要看这个</strong>， 能在结果落到文件之前就发现它改错了。</p><p><strong>规划中</strong> 它还在&quot;想&quot;——分析需求、整理执行思路的阶段，还没开始动手。 说明白一点：这是它拆解任务的时间，不是卡住了。</p><p><strong>待确认</strong> 它停下来等你回答。<strong>这是最需要你介入的状态</strong>，你不回话它就一直停着。 常见于它需要你选一个方案、确认某个文件、或者缺信息做不下去。</p><p><strong>已完成未读</strong> 活干完了，但你还没打开结果区看。<strong>看到图标就该去验收</strong>， 它不会主动告诉你结果对不对。</p><p><strong>归档 vs 删除</strong> 归档 = 收起来，以后还能在设置里找到。删除 = <strong>永久消失，所有设备上都清掉， 恢复不了</strong>。不确定就归档，别删。</p><p><strong>上下文管理（继续处理已有任务）</strong> 不用重新开一个任务再讲一遍。打开旧任务补一句就行，它记得之前聊过什么， 直接在原有基础上往下做。任务失败要重试、或想扩展之前的结果，都用这招。</p><hr><p><em>下一篇：第 5 章 加载一个真正用得上的 Skill——把重复的活变成一条指令。</em></p>',88)])])}const P=o(c,[["render",b]]);export{x as __pageData,P as default};
